INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(114539, 'ruRU', '', 'Рад снова тебя видеть, $n.', 24330),
(114540, 'ruRU', '', 'Нам нужно быть осторожными. Иссохшие рыщут по этой местности, ненасытно алча и магии, и плоти.', 24330),
(114541, 'ruRU', '', 'Держись рядом!', 24330),
(114542, 'ruRU', '', 'Не будь глупцом, чужак. Мой барьер защитит тебя.', 24330),
(114548, 'ruRU', '', 'Мы должны немедленно освободить Хранителя Ремула! Я знаю короткий путь к пещере, где его держат. Идём, $n. Следуй за мной!', 24330),
(114550, 'ruRU', '', 'Надеюсь, мы не опоздали, чтобы спасти Хранителя Ремула.', 24330),
(114552, 'ruRU', '', 'Я знаю кое-кого, кто предпочёл бы погоню за властью нуждам других...', 24330),
(114560, 'ruRU', '', 'Я прикажу своим людям связаться с твоими людьми. Как звучит?', 24330),
(114561, 'ruRU', '', 'Ага. Мхм. Ну да. Я полностью внимаю.', 24330),
(114562, 'ruRU', '', 'О, ты один из тех разбойников.', 24330),
(114580, 'ruRU', '', 'Добро пожаловать на борт, $n.\n\nМы полностью снаряжены и готовы отправиться в путь, как только будешь готов ты.', 24330),
(114594, 'ruRU', '', 'Совет в надёжных руках с тобой во главе.', 24330),
(114618, 'ruRU', '', 'Ты станешь первым испытанием для моего нового подопытного!', 24330),
(114619, 'ruRU', '', 'Готов вернуться в тюрьму? Здесь мы мало чем поможем.\n\nНам следует вернуться к союзникам и помочь одолеть Хаккара, прежде чем у него будет шанс обрушить своих тварей на город.', 24330),
(114637, 'ruRU', '', 'Слуга Древних богов! Давайте поглотим его!', 24330),
(114638, 'ruRU', '', 'Вон! Шпион Н''Зота! Нам следует убить его.', 24330),
(114639, 'ruRU', '', 'Видишь это? Бедного носителя уже не спасти, остаётся лишь прекратить его мучения.', 24330),
(114643, 'ruRU', '', '<Талисра прикладывает руку к своей исхудавшей щеке.>$B$BМоё тело истощилось так быстро...$B$BКажется, мы, Ночнорождённые, живём каждый день на лезвии ножа.', 24330),
(114644, 'ruRU', '', 'Я освобожу Сурамар от Легиона, но сначала мне нужно восстановить силы.$B$BИ нам нужен план...', 24330),
(114645, 'ruRU', '', 'Надеюсь, моим товарищам повезло больше, чем мне.', 24330),
(114655, 'ruRU', '', 'С гибелью Хаккара жители Даларана будут в безопасности. Большинство из них никогда не узнает об угрозе, с которой они столкнулись, благодаря твоим героическим действиям.', 24330),
(114656, 'ruRU', '', 'Ты сразил демонического лорда, прежде чем он успел терроризировать город. Ты сохранил верность клятве, которую мы все принесли — наблюдать и защищать.', 24330),
(114657, 'ruRU', '', 'Было бы наивно полагать, что это последняя угроза, с которой столкнётся Азерот.', 24330),
(114658, 'ruRU', '', 'Пылающий Легион стоит у нашего порога, требуя, чтобы с ним считались.', 24330),
(114659, 'ruRU', '', 'В такие времена наша клятва важна как никогда.', 24330),
(114661, 'ruRU', '', 'Мы сражаемся не за славу, не за известность и не за богатства.', 24330),
(114662, 'ruRU', '', 'Мы существуем, чтобы защищать тех, кто нуждается в этом больше всего, часто без награды и признания.', 24330),
(114664, 'ruRU', '', 'Мы наблюдатели в глуши.', 24330),
(114665, 'ruRU', '', 'Мы орёл на ветру.', 24330),
(114666, 'ruRU', '', 'Мы идём по одинокой дороге.', 24330),
(114667, 'ruRU', '', 'Ибо наш путь — Незримый Путь.', 24330),
(114716, 'ruRU', '', 'Как трогательно. Ещё несколько защитников. Как будто это хоть чем-то поможет.', 24330),
(114719, 'ruRU', '', '...и чтобы доказать, что ты не в безопасности, даже здесь, на Демоническом Молоте.', 24330),
(114721, 'ruRU', '', 'Великая сила будет дарована тем, кто присоединится к нам. Мучительная агония ждёт тех, кто откажется.', 24330),
(114723, 'ruRU', '', 'Тс-тс, Вередис. Честно есть честно. До новой встречи во плоти, $n.', 24330),
(114745, 'ruRU', '', 'Могущественный волшебник Падавсен был захвачен Хумонгрисом. Найди Хумонгриса и убей его, прежде чем он убьёт Падавсена.', 24330),
(114746, 'ruRU', '', 'Хумонгрис мёртв, а Падавсен жив. Отлично сделано.', 24330),
(114748, 'ruRU', '', 'Тебе не убить меня, даже если ты будешь пытаться сотню лет!', 24330),
(114749, 'ruRU', '', 'Каждому суждено однажды умереть.', 24330),
(114751, 'ruRU', '', 'Ты осквернил древние пути, мистик! Король-Бог не достоин Чертогов Доблести!', 24330);
